    long long n;
    cin >> n;

    __int128 best = (__int128)1 << 126;

    if (0 > (__int128)n)
        best = 0;

    __int128 power = 1;
    for (int k = 0; k <= 19; ++k) {
        for (int digit = 1; digit <= 9; ++digit) {
            __int128 value = power * digit;

            if (value > n)
